package com.ejemplo.alquileres.service;
 import com.ejemplo.alquileres.model.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.time.*; import java.time.temporal.*;
 @Service @RequiredArgsConstructor public class MorosidadService { private final ConfiguracionService configuracion; private final Clock clock; public SemaforoMorosidad semaforo(Contrato contrato){LocalDate hoy=LocalDate.now(clock);long cantidad=0,max=0;for(Cuota c:contrato.getCuotas())if((c.getEstado()==EstadoCuota.PENDIENTE||c.getEstado()==EstadoCuota.PARCIAL)&&c.getFechaVencimiento().plusDays(contrato.getDiasGracia()).isBefore(hoy)){cantidad++;max=Math.max(max,ChronoUnit.DAYS.between(c.getFechaVencimiento(),hoy));}if(cantidad==0)return SemaforoMorosidad.AL_DIA;if(max>configuracion.umbralLeveDias()||cantidad>=configuracion.cuotasRojo())return SemaforoMorosidad.MOROSO;return SemaforoMorosidad.ATRASO_LEVE;} }
